<script setup lang="ts">defineOptions({ inheritAttrs: false }); import GText from '../../content/GText/GText.vue'; import type { TextContent } from '@/shared/types/components'; const props = withDefaults(defineProps<{ accept?: string; multiple?: boolean; disabled?: boolean; label?: TextContent }>(), { label: () => ({ table: 'Common', textKey: '#SELECT_FILE' }) }); const emit = defineEmits<{ change: [files: FileList | null] }>(); function onChange(event: Event) { emit('change', (event.target as HTMLInputElement).files) }</script>
<template><label class="ew-file-picker"><span><slot><GText :content="props.label" /></slot></span><input v-bind="$attrs" type="file" :accept="props.accept" :multiple="props.multiple" :disabled="props.disabled" @change="onChange" /></label></template>
